mapper.select:
SELECT COALESCE(DOWNLOAD_COUNT, 0)
FROM DOCS_REQUEST_FILE
WHERE REQUEST_NO = #{requestNo}
  AND OBJECT_ID = #{objectId}
  AND FILE_NO::text = #{fileNo}
  AND DESTROY_TYPE IS NULL

mapper.update:
UPDATE DOCS_REQUEST_FILE
SET DOWNLOAD_COUNT = COALESCE(DOWNLOAD_COUNT, 0) + 1
WHERE REQUEST_NO = #{requestNo}
  AND OBJECT_ID = #{objectId}
  AND FILE_NO::text = #{fileNo}
  AND DESTROY_TYPE IS NULL
  AND COALESCE(DOWNLOAD_COUNT, 0) < 3

