SELECT COUNT(*)
  FROM DOCS_REQUEST_FILE rf
  JOIN DOCS_REQUEST r ON r.REQUEST_NO = rf.REQUEST_NO
 WHERE rf.REQUEST_NO = #{requestNo}
   AND rf.OBJECT_ID = #{objectId}
   AND (NULLIF(#{fileNo}, '') IS NULL OR rf.FILE_NO::text = #{fileNo})
   AND (
        r.INSERT_USER_CD = #{userCd}
        OR EXISTS (
            SELECT 1 FROM DOCS_REQUEST_DEPLOY rd
             WHERE rd.REQUEST_NO = r.REQUEST_NO
               AND rd.DEPLOY_USER_CD = #{userCd}
        )
        OR EXISTS (
            SELECT 1 FROM DOCS_ROLE_GROUP_MEMBER rgm
             WHERE rgm.GROUP_CODE = 'RG_001'
               AND rgm.GROUP_TYPE = 'USER'
               AND rgm.MEMBER_CD = #{userCd}
        )
   )
